        if t:
            yield t


def pipeline(textos):
    return sem_vazios(normalizados(textos))

def janelas(tokens, k):
    if k <= 0:
        return
    janela = []
    for token in tokens:
        janela.append(token)
        if len(janela) > k:
            janela.pop(0)
        if len(janela) == k:
            yield list(janela)

