import json

PADROES = {"modelo": "mock-mini", "temperatura": 0.7, "max_tokens": 256}

def carregar_config(caminho):
    try:
        with open(caminho, encoding="utf-8") as f:
            texto = f.read()
    except FileNotFoundError:
        return dict(PADROES)
    try:
        dados = json.loads(texto)
    except json.JSONDecodeError:
        raise ValueError(f"JSON inválido em {caminho}")
