from dataclasses import dataclass

@dataclass
class ConfigGeracao:
    modelo: str
    temperatura: float = 1.0
    max_tokens: int | None = None

    def __post_init__(self):
        if not 0 <= self.temperatura <= 2:
            raise ValueError(f"temperatura fora da faixa 0-2: {self.temperatura}")
        if self.max_tokens is not None and self.max_tokens <= 0:
            raise ValueError(f"max_tokens deve ser positivo: {self.max_tokens}")

    @classmethod
    def from_dict(cls, dados):
        return cls(dados["modelo"], dados.get("temperatura", 1.0),
                   dados.get("max_tokens"))

